import ru.bccontrol.sedonastudio.model.*;import ru.bccontrol.sedonastudio.protocol.*;import java.nio.file.*;import java.util.*;
public class LocalSoxTest {
 static Project.Node find(List<Project.Node> catalog,String qname){for(Project.Node n:catalog)if(n.type.equals(qname))return n.copy();throw new AssertionError(qname);}
 static Project.Node named(Project p,String name){for(Project.Node n:p.nodes.values())if(n.name.equals(name))return n;throw new AssertionError("Missing "+name);}
 public static void main(String[] args)throws Exception{Path out=Paths.get(args[0]);SoxDeviceSession session=new SoxDeviceSession();try{
 Project initial=session.connect("127.0.0.1",13987,"admin","localJarTest".toCharArray());if(session.downloadManifests()!=5)throw new AssertionError("Explicit manifest download");if(initial.parts.size()!=5)throw new AssertionError("Cold schema");List<Project.Node> catalog=session.catalog();Project draft=initial.copy();Project.Node a=find(catalog,"types::ConstFloat"),b=find(catalog,"math::Add2");a.id="draft-a";a.name="src1";a.parent="0";a.x=120;a.y=120;a.values.put("out","14.5");a.values.put("meta","3");b.id="draft-b";b.name="sum1";b.parent="0";b.x=480;b.y=120;draft.nodes.put(a.id,a);draft.nodes.put(b.id,b);draft.connect(a.id,"out",b.id,"in1");a.icon="!";a.info=true;a.infoSource="type";
 Project.Caption attached=new Project.Caption();attached.id="note-create";attached.anchor=a.id;attached.text="Readback annotation";attached.color="green";draft.captions.add(attached);
 Project created=session.apply(initial,draft,false,out.resolve("01-create"));Project.Node actual=named(created,"src1"),sum=named(created,"sum1");if(!actual.icon.equals("!")||!actual.infoSource.equals("type")||created.captions.size()!=1||!created.captions.get(0).anchor.equals(actual.id))throw new AssertionError("Local icon/info/caption remap lost after create");
 if((Integer.parseInt(actual.values.get("meta"))&15)!=3)throw new AssertionError("Copied security group lost");if(!Files.exists(out.resolve("01-create/saved-app-before.sab"))||!Files.exists(out.resolve("01-create/kits-before.scode")))throw new AssertionError("Mandatory file backups missing");if(!new String(Files.readAllBytes(out.resolve("01-create/journal.log")),"UTF-8").contains("ATTEMPT ADD"))throw new AssertionError("Write-ahead intent missing");if(!actual.values.get("out").equals("14.5"))throw new AssertionError("Create config");if(created.wires.stream().noneMatch(w->w.source.equals(actual.id)&&w.target.equals(sum.id)))throw new AssertionError("Link readback");
 Project collision=created.copy();collision.remove(sum.id);collision.nodes.get(actual.id).name="sum1";boolean nameRejected=false;try{session.apply(created,collision,false,out.resolve("name-collision"));}catch(IllegalArgumentException expected){nameRejected=true;}if(!nameRejected||session.read().wires.size()!=created.wires.size())throw new AssertionError("Name collision must reject before unlink");
 Project changed=created.copy();changed.nodes.get(actual.id).values.put("out","27.25");changed.nodes.get(actual.id).name="src2";changed.nodes.get(actual.id).x=240;Project after=session.apply(created,changed,false,out.resolve("02-edit"));if(!named(after,"src2").values.get("out").equals("27.25"))throw new AssertionError("Value readback");if(named(after,"src2").x!=240)throw new AssertionError("Meta coordinates");if(!session.sample(actual.id).get("out").equals("27.25"))throw new AssertionError("Selective sampling");
 Project stale=after.copy(),desired=after.copy();stale.nodes.get(actual.id).values.put("out","1.0");desired.nodes.get(actual.id).values.put("out","2.0");boolean rejected=false;try{session.apply(stale,desired,false,out.resolve("03-stale"));}catch(IllegalStateException expected){rejected=true;}if(!rejected||!session.sample(actual.id).get("out").equals("27.25"))throw new AssertionError("Stale write mutated device");
 Project grouped=after.copy();Project.Node folder=find(catalog,"sys::Folder");folder.id="draft-folder";folder.name="group";folder.parent="0";folder.x=600;folder.y=360;grouped.nodes.put(folder.id,folder);
 Project.Node copy=grouped.nodes.get(actual.id);copy.values.put("meta",Integer.toString(Integer.parseInt(copy.values.get("meta"))|3));copy.note="Preserved local note";grouped.wires.get(0).bends.add(new Project.Point(360,180));
 Project withFolder=session.apply(after,grouped,false,out.resolve("05-folder"));Project relocated=withFolder.copy();String oldId=named(relocated,"src2").id;String folderId=named(relocated,"group").id;EditorCommands.relocate(relocated,List.of(oldId),folderId);Project moved=session.apply(withFolder,relocated,false,out.resolve("06-relocate"));Project.Node movedNode=moved.nodes.values().stream().filter(n->n.parent.equals(folderId)&&n.type.equals("types::ConstFloat")).findFirst().orElseThrow();if((Integer.parseInt(movedNode.values.get("meta"))&15)!=3||!movedNode.note.equals("Preserved local note"))throw new AssertionError("Relocation security/local note");if(moved.wires.stream().noneMatch(w->w.source.equals(movedNode.id)&&w.target.equals(sum.id)))throw new AssertionError("Relocation external wire");if(moved.nodes.containsKey(oldId))throw new AssertionError("Relocation original remains");
 if(moved.captions.size()!=1||!moved.captions.get(0).anchor.equals(movedNode.id)||!movedNode.infoSource.equals("type"))throw new AssertionError("Caption and description lost across relocation readback");
 System.out.println("PASS native folder relocation: create/relink/delete, external edge, metadata groups and note retained");
 Project without=moved.copy();without.remove(folderId);without.remove(sum.id);Project clean=session.apply(moved,without,false,out.resolve("04-delete"));if(clean.nodes.size()!=initial.nodes.size())throw new AssertionError("Delete cleanup");session.close();if(session.connected())throw new AssertionError("Close");System.out.println("PASS local native SVM: empty cache -> manifest GET fallback -> 5-kit schema; create/config/link/readback; rename/value/meta; selective reads; stale-write and occupied-name rejection before mutation; unlink/delete; disconnect. Physical devices untouched.");
 }finally{session.close();}}
}
